using System.Text.Json;
using System.Text.Json.Nodes;
using Metarill.Core.Metadata;
using Xunit;
namespace Metarill.Generation.Tests;
/// <summary>原共享前缀由元数据生成完整协调服务，不手改派生产物。</summary>
[Collection(StandaloneProcessBudgetCollection.Name)]
public sealed class SharedCrossTableGenerationTests
{
    /// <summary>四种键及短控件共享叶子实际生成、编译，缓存每个物理列只登记一次。</summary>
    [Theory][InlineData("string","string",false)][InlineData("string","int64",false)][InlineData("int64","string",false)][InlineData("int64","int64",false)][InlineData("string","int64",true)][InlineData("int64","string",true)]
    public async Task Actual_generated_services_compile_with_atomic_shared_coordination(string type,string parent,bool shorter)
    {
        var c=Catalog("shared_cross",type,parent,shorter);var before=JsonSerializer.Serialize(c);var m=GenerationModel.Create(c,"Example.SharedCross");var table=m.Tables.Single(t=>t.Source.Id=="2");var page=Assert.Single(table.Pages);var group=Assert.Single(SharedCrossTableCompilation.ForPage(m,table,page).Groups);Assert.Equal(2,group.Plans.Count);Assert.Empty(SharedCrossTableCompilation.ForPage(m,table,page).Gaps);Assert.Equal(2,CrossTableWriteCompilation.ForService(m,table,page).Count);var bindings=RelationPropagationCompilation.Bindings(m);Assert.Equal(shorter?3:4,bindings.Count);if(shorter)Assert.Equal("25",bindings.Single(b=>b.Cache.Source.ColumnName=="area_name").CrossTableColumnId);Assert.Empty(GenerationCapabilityAudit.Collect(m));var boundary=Path.Combine(Path.GetTempPath(),"metarill-shared-cross-generation");var directory=Path.Combine(boundary,Guid.NewGuid().ToString("N"));
        try{new CSharpGenerator().Generate(c,Path.Combine(directory,"generated"),m.Namespace);await GeneratedRelationOptionsMySqlTests.BuildGenerated(directory);var source=await File.ReadAllTextAsync(Path.Combine(directory,"generated/Services/SharedCrossSourceService.g.cs"));Assert.Contains("NormalizeSharedCross201_25Async",source);Assert.Contains("var originalCrossShared=",source);Assert.Contains("originalCrossShared:originalCrossShared",source);var hand=Path.Combine(directory,"generated/Services/SharedCrossSourceService.cs");await File.AppendAllTextAsync(hand,"\n// 共享级联手写扩展保留。\n");var bytes=await File.ReadAllBytesAsync(hand);new CSharpGenerator().Generate(c,Path.Combine(directory,"generated"),m.Namespace);Assert.Equal(bytes,await File.ReadAllBytesAsync(hand));Assert.Equal(before,JsonSerializer.Serialize(c));}finally{await TestDirectoryCleanup.DeleteAsync(directory,boundary);}
    }
    /// <summary>实际Full包保留原组件；共享组只新增已确认清理事件，原Vue探针另执行。</summary>
    [Theory][InlineData(false,false)][InlineData(true,false)][InlineData(false,true)]
    public async Task Full_application_builds_with_original_component(bool shorter,bool derived)
    {
        var c=Catalog("shared_cross","string","int64",shorter,derived);var root=NonRedundantApplicationFixture.Root();var boundary=Path.Combine(Path.GetTempPath(),"metarill-shared-cross-full");var directory=Path.Combine(boundary,Guid.NewGuid().ToString("N"));
        try{new ApplicationPackager().Create(c,directory,"Example.SharedCrossFull",root);foreach(var action in new[]{"restore","build"})await NonRedundantApplicationFixture.BuildAsync(directory,action);Assert.Equal(File.ReadAllBytes(Path.Combine(root,"frontend/metarill_uni_admin/components/yzp-cascade-tree/yzp-cascade-tree.vue")),File.ReadAllBytes(Path.Combine(directory,"frontend/components/yzp-cascade-tree/yzp-cascade-tree.vue")));var detail=await File.ReadAllTextAsync(Path.Combine(directory,"frontend/pages/yzp/shared_cross_source-detail-201.vue"));Assert.Contains("hasOwnProperty.call(incoming",detail);Assert.Contains("warehouseId",detail);Assert.Contains("receiveCascadeTree25",detail);Assert.Contains("receiveCascadeTree80",detail);var probe=NonRedundantApplicationFixture.Start("node",directory);probe.ArgumentList.Add(Path.Combine(NonRedundantApplicationFixture.TestDirectory(),"SharedCrossTableVueProbe.mjs"));probe.ArgumentList.Add(Path.Combine(directory,"frontend"));probe.ArgumentList.Add(shorter.ToString().ToLowerInvariant());await NonRedundantApplicationFixture.RunAsync(probe);}finally{await TestDirectoryCleanup.DeleteAsync(directory,boundary);}
    }
    /// <summary>不同范围／祖先、坏同伴及冲突R0／全局变量／来源自参与不能借共享组放开。</summary>
    [Theory][InlineData("differentName")][InlineData("ancestor")][InlineData("badPeer")][InlineData("sourceR0Default")][InlineData("globalVariable")][InlineData("self")]
    public void Invalid_shared_group_rejects_all_members_before_full_stage(string kind)
    {
        var c=Catalog("shared_cross","string","int64",false);var second=c.ConfigColumns.Single(x=>x.Id=="80");var json=JsonNode.Parse(second.ControlDetail)!;
        if(kind=="differentName"){c.ConfigColumns.Add(new(){Id="39",YzProjectId=c.YzProjectId,ConfigTableId="3",ColumnName="caption",LogicalType="string"});c.ConfigPageColumns.Add(new(){Id="30139",ConfigPageId="301",ConfigColumnId="39"});json["levels"]![0]!["nameField"]="caption";}
        if(kind=="ancestor")json["levels"]![0]!["columnPrefix"]="other_country";if(kind=="badPeer")json["levels"]![2]!["nameField"]="missing";if(kind=="sourceR0Default"){c.ConfigTables.Single(x=>x.Id=="2").IsRongyu=0;second.DefaultValue="1";}
        if(kind=="globalVariable"){c.ConfigTables.Single(x=>x.Id=="3").Extra["scopeKind"]=JsonSerializer.SerializeToElement("global");c.ConfigPages.Single(x=>x.Id=="301").WhereSql="yz_project_id=@current_yz_project_id AND status=1";}
        if(kind=="self"){foreach(var control in c.ConfigColumns.Where(x=>x.Id is "25" or "80")){var definition=JsonNode.Parse(control.ControlDetail)!;definition["levels"]![0]!["table"]="shared_cross_source";control.ControlDetail=definition.ToJsonString();}json["levels"]![0]!["table"]="shared_cross_source";c.ConfigColumns.Single(x=>x.Id=="45").LinkConfigTableId="2";}
        second.ControlDetail=json.ToJsonString();var m=GenerationModel.Create(c,"Example.BadSharedCross");var t=m.Tables.Single(t=>t.Source.Id=="2");var page=Assert.Single(t.Pages);Assert.Empty(CrossTableWriteCompilation.ForService(m,t,page));var boundary=Path.Combine(Path.GetTempPath(),"metarill-bad-shared-cross");var output=Path.Combine(boundary,Guid.NewGuid().ToString("N"));Assert.ThrowsAny<Exception>(()=>new ApplicationPackager().Create(c,output,m.Namespace,NonRedundantApplicationFixture.Root()));Assert.False(Directory.Exists(output));
    }
    /// <summary>同一源表共用国家／地区；第二控件的独立末级真实指向仓库表。</summary>
    internal static MetadataCatalog Catalog(string prefix,string type,string parent,bool shorter=false,bool derived=false)
    {
        var c=CrossTableNameCacheGenerationTests.Catalog(prefix,type,parent,false);var source=c.ConfigColumns.Single(x=>x.Id=="25");var original=JsonNode.Parse(source.ControlDetail)!;var warehouse=JsonNode.Parse(source.ControlDetail)!;warehouse["levels"]![2]!["key"]="warehouse";warehouse["levels"]![2]!["table"]=prefix+"_warehouse";warehouse["levels"]![2]!["columnPrefix"]="warehouse";
        c.ConfigTables.Add(new(){Id="8",TableName=prefix+"_warehouse",IsRongyu=1});c.ConfigColumns.AddRange([new(){Id="81",ConfigTableId="8",ColumnName="id",LogicalType="int64",IsDbNotNull=1},new(){Id="82",ConfigTableId="8",ColumnName="name",LogicalType="string"},new(){Id="83",ConfigTableId="8",ColumnName="yz_project_id",LogicalType="int64"},new(){Id="84",ConfigTableId="8",ColumnName="delete_no",LogicalType="datetime"},new(){Id="85",ConfigTableId="8",ColumnName=prefix+"_area_id",LogicalType=parent,LinkConfigTableId="4"},new(){Id="86",ConfigTableId="8",ColumnName="status",LogicalType="int32"},new(){Id="80",ConfigTableId="2",ColumnName="warehouse_id",LogicalType=type,ControlKind="CascadeTree",ControlDetail=warehouse.ToJsonString(),LinkConfigTableId="8"}]);c.ConfigPages.Add(new(){Id="801",ConfigTableId="8",WhereSql="yz_project_id=@current_yz_project_id AND status=1",IsSave=1});foreach(var id in new[]{"82","85"})c.ConfigPageColumns.Add(new(){Id="801"+id,ConfigPageId="801",ConfigColumnId=id});c.ConfigPageColumns.Add(new(){Id="20180",ConfigPageId="201",ConfigColumnId="80"});
        if(shorter){source.ColumnName="area_id";source.LinkConfigTableId="4";original["levels"]!.AsArray().RemoveAt(2);source.ControlDetail=original.ToJsonString();}if(derived)NonRedundantCrossTargetsTests.Apply(c,prefix,"derived");RedundantMultiNameCacheTests.Published(c);foreach(var page in c.ConfigPages)c.ConfigMenus.Add(new(){Id=(700000+int.Parse(page.Id,System.Globalization.CultureInfo.InvariantCulture)).ToString(System.Globalization.CultureInfo.InvariantCulture),YzProjectId=c.YzProjectId,YzAdminTypeId="5",Name="共享级联"+page.Id,Kind="GENERATED_PAGE",ConfigPageId=page.Id});return c;
    }
}
